    $context = @{ branch = ""; modified = @(); staged = @(); recentCommits = @() }
    try {
        $branch = git -C $ProjectRoot rev-parse --abbrev-ref HEAD 2>$null
        if ($branch) { $context.branch = $branch.Trim() }
    } catch {}
    try {
        $modified = git -C $ProjectRoot diff --name-only 2>$null
        if ($modified) { $context.modified = @($modified) }
    } catch {}
    try {
        $staged = git -C $ProjectRoot diff --cached --name-only 2>$null
        if ($staged) { $context.staged = @($staged) }
    } catch {}
    try {
        $log = git -C $ProjectRoot log --oneline -5 2>$null
        if ($log) { $context.recentCommits = @($log) }
    } catch {}
    return $context
}

function Get-FileContext {
    $maxAge = [DateTime]::Now.AddHours(-2)
    $recentFiles = @()
    $extensions = @('.ps1', '.md', '.json', '.ts', '.js', '.go', '.py', '.yaml', '.yml', '.toml', '.cfg')
    $searchDirs = @('scripts', 'config', 'src', 'skills', 'docs', 'rules', '.github')
    foreach ($dir in $searchDirs) {
        $path = Join-Path $ProjectRoot $dir
        if (Test-Path $path) {
            try {
                $files = Get-ChildItem -Path $path -Recurse -File -ErrorAction SilentlyContinue |
                    Where-Object { $_.LastWriteTime -gt $maxAge -and $extensions -contains $_.Extension -and $_.Length -lt 100KB } |
                    Select-Object -First 20
                foreach ($f in $files) {
                    $relPath = $f.FullName.Substring($ProjectRoot.Length + 1)
                    $recentFiles += $relPath
                }
            } catch {}
        }
    }
    return $recentFiles
}

function Get-ConfigContext {
    $context = @{}
    $autoDelegPath = Join-Path $ProjectRoot "config\auto-delegation.json"
    if (Test-Path $autoDelegPath) {
        try {
            $cfg = Get-Content $autoDelegPath -Raw | ConvertFrom-Json
            $context.enabled = $cfg.enabled
            $context.confidenceThreshold = $cfg.confidenceThreshold
        } catch {}
    }
    $orchestratorPath = Join-Path $ProjectRoot "config\orchestrator.json"
    if (Test-Path $orchestratorPath) {
        try {
            $cfg = Get-Content $orchestratorPath -Raw | ConvertFrom-Json
            $context.agentCount = @($cfg.agents.PSObject.Properties).Count
        } catch {}
    }
    return $context
}

$gitCtx = Get-GitContext
$files = Get-FileContext
$configCtx = Get-ConfigContext

$contextText = @()
if ($gitCtx.branch) { $contextText += "branch: $($gitCtx.branch)" }
foreach ($f in $gitCtx.modified) { $contextText += "modified: $f" }
foreach ($f in $gitCtx.staged) { $contextText += "staged: $f" }
foreach ($c in $gitCtx.recentCommits) { $contextText += "commit: $c" }
foreach ($f in $files) { $contextText += "active: $f" }

$result = @{
    timestamp = (Get-Date -Format "o")
    projectRoot = $ProjectRoot
    git = $gitCtx
    recentFiles = $files
    config = $configCtx
    contextText = ($contextText -join " | ")
}

if ($Raw) {
    $result | ConvertTo-Json -Depth 5
    return
}

Write-Host "=== Workspace Context Analysis ===" -ForegroundColor Cyan
Write-Host "Branch:       $($gitCtx.branch)" -ForegroundColor Green
Write-Host "Modified:     $($gitCtx.modified.Count) files" -ForegroundColor Yellow
