    $autoDelegPath = Join-Path $ProjectRoot "config\auto-delegation.json"
    if (Test-Path $autoDelegPath) {
        try {
            $cfg = Get-Content $autoDelegPath -Raw | ConvertFrom-Json
            $context.enabled = $cfg.enabled
            $context.confidenceThreshold = $cfg.confidenceThreshold
        } catch {}
    }
    $orchestratorPath = Join-Path $ProjectRoot "config\orchestrator.json"
    if (Test-Path $orchestratorPath) {
        try {
            $cfg = Get-Content $orchestratorPath -Raw | ConvertFrom-Json
            $context.agentCount = @($cfg.agents.PSObject.Properties).Count
        } catch {}
    }
    return $context
}

$gitCtx = Get-GitContext
$files = Get-FileContext
$configCtx = Get-ConfigContext

$contextText = @()
if ($gitCtx.branch) { $contextText += "branch: $($gitCtx.branch)" }
foreach ($f in $gitCtx.modified) { $contextText += "modified: $f" }
foreach ($f in $gitCtx.staged) { $contextText += "staged: $f" }
foreach ($c in $gitCtx.recentCommits) { $contextText += "commit: $c" }
foreach ($f in $files) { $contextText += "active: $f" }

$result = @{
    timestamp = (Get-Date -Format "o")
    projectRoot = $ProjectRoot
    git = $gitCtx
    recentFiles = $files
    config = $configCtx
    contextText = ($contextText -join " | ")
}

if ($Raw) {
    $result | ConvertTo-Json -Depth 5
    return
}

Write-Host "=== Workspace Context Analysis ===" -ForegroundColor Cyan
Write-Host "Branch:       $($gitCtx.branch)" -ForegroundColor Green
Write-Host "Modified:     $($gitCtx.modified.Count) files" -ForegroundColor Yellow
Write-Host "Staged:       $($gitCtx.staged.Count) files" -ForegroundColor Yellow
Write-Host "Recent files: $($files.Count) files (last 2h)" -ForegroundColor DarkGray
Write-Host "Context:      '$($result.contextText.Substring(0, [Math]::Min(120, $result.contextText.Length)))...'" -ForegroundColor DarkGray

return $result
