function Get-GitContext {
    $context = @{ branch = ""; modified = @(); staged = @(); recentCommits = @() }
    try {
        $branch = git -C $ProjectRoot rev-parse --abbrev-ref HEAD 2>$null
        if ($branch) { $context.branch = $branch.Trim() }
